// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var draw = SVG().addTo(container).size('100%', '100%');

var D2R = Math.PI / 180;
// Ground distance from the foot of the altitude to milepost A is FIXED
// (A is a fixed point on the highway). It is chosen so the default state
// h = 2.5 mi reproduces the textbook figure's 49 degree depression angle.
var XA = 2.5 / Math.tan(49 * D2R);   // 2.1732 mi

var COL = {
  teal: '#159b91',
  sight: '#8d8d8d',
  road: '#111111',
  orange: '#e08214',
  blue: '#4a6fa5',
  body: '#c7cde3',
  mid: '#8c96c0',
  navy: '#3d4a82',
  dark: '#2b3566'
};

var PHASES = ['horizontal reference', 'two right triangles', 'label unknowns', 'write equations'];
var state = { h: 2.5, d: 3.2, phase: 0 };
var FS = 12, LW = 1.5, SCALE = 60;
var firstDone = false;

/* ── helpers ─────────────────────────────────────────────── */
function innerSize() {
  var st = getComputedStyle(container);
  var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
  var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
