function brace(x1, x2, y, dir, label, color) {
  var g = draw.group();
  var tl = Math.max(3, FS * 0.42);
  g.line(x1, y, x2, y).stroke({ color: color, width: LW * 0.9 });
  g.line(x1, y - tl, x1, y + tl).stroke({ color: color, width: LW * 0.9 });
  g.line(x2, y - tl, x2, y + tl).stroke({ color: color, width: LW * 0.9 });
  txt(label, (x1 + x2) / 2, y + dir * FS * 1.0, { size: FS, italic: true, fill: color });
  return g;
}

function drawPlane(vx, vy, s) {
  var g = draw.group();
  g.path('M-64,-7 L-34,-20 L-22,-18 L-46,-6 Z').fill(COL.mid);
  g.path('M-100,7 C-96,-1 -78,-7 -52,-9 L-14,-11 C-4,-11 1,-5 -4,1 C-11,8 -48,14 -78,13 C-92,12 -99,11 -100,7 Z')
    .fill(COL.body).stroke({ color: '#67719c', width: 1.2 });
  g.path('M-24,-10 L-8,-34 L2,-33 L-2,-8 Z').fill(COL.navy);
  g.path('M-14,-8 L4,-14 L11,-12 L-6,-5 Z').fill('#4c5a95');
  g.path('M-58,3 L-26,18 L-8,18 L-38,1 Z').fill(COL.navy);
  g.ellipse(20, 9).center(-52, 6).fill('#48568e');
  g.ellipse(15, 7).center(-40, -3).fill('#6a75a8');
  g.path('M-98,3 C-94,-2 -89,-4 -85,-4 L-87,3 Z').fill(COL.dark);
  g.ellipse(9, 4).center(-70, 1).fill('#8e98c2').opacity(0.8);
  g.attr('transform', 'translate(' + vx + ',' + vy + ') scale(' + s + ')');
  return g;
}

/* ── main render ─────────────────────────────────────────── */
function render() {
  var sz = innerSize(), Wp = sz.w, Hp = sz.h;
  FS = Math.max(8, Math.min(15, Wp / 48));
  LW = Math.max(0.9, Math.min(2.2, Wp / 430));

  var h = state.h, d = state.d, ph = state.phase;
  var xB = XA + d;

  var below = (ph >= 2) ? FS * 6.2 : FS * 2.8;
  var topPad = FS * 0.5;
  var xmin = -2.35, xmax = xB + 0.75;
  var worldTop = h + 0.85;
  var scale = Math.min(Wp / (xmax - xmin), Math.max(20, Hp - below - topPad) / worldTop);
  SCALE = scale;

  var wSpan = Wp / scale, hSpan = Hp / scale;
  var xc = (xmin + xmax) / 2;
  var x0 = xc - wSpan / 2;
  var cb = -below / scale, ct = worldTop;
  var extra = hSpan - (ct - cb);
  var y0 = cb - extra / 2;

  setPlotFrame({ xDomain: [x0, x0 + wSpan], yDomain: [y0, y0 + hSpan], margin: 0, draw: draw });
  draw.clear();

  var PXs = plotX(0), PYs = plotY(h);
  var FXs = plotX(0), FYs = plotY(0);
  var AXs = plotX(XA), BXs = plotX(xB);
  var roadL = plotX(-0.55), roadR = plotX(xmax - 0.02);

  var aA = Math.atan2(h, XA), aB = Math.atan2(h, xB);
  var aAd = Math.round(aA / D2R), aBd = Math.round(aB / D2R);
  var PA = Math.sqrt(h * h + XA * XA), PB = Math.sqrt(h * h + xB * xB);

  /* highlighted right triangles (phase >= 1) */
  if (ph >= 1) {
    draw.polygon([[PXs, PYs], [FXs, FYs], [BXs, FYs]].map(function (p) { return p.join(','); }).join(' '))
      .fill({ color: COL.blue, opacity: 0.08 }).stroke('none');
    var triA = draw.polygon([[PXs, PYs], [FXs, FYs], [AXs, FYs]].map(function (p) { return p.join(','); }).join(' '))
      .fill({ color: COL.orange, opacity: 0.14 }).stroke('none');
    hoverable(triA, 'Small right triangle P–F–A: legs h and x, angle at P = ' + (90 - aAd) + '°',
      'The nested right triangles',
      'Both triangles have the same vertical leg h and both have their right angle at the foot F. The small one closes at A with ground leg x; the large one closes at B with ground leg x + d.');
  }

  /* highway */
  var road = draw.line(roadL, FYs, roadR, FYs).stroke({ color: COL.road, width: Math.max(1.4, LW * 1.25), linecap: 'square' });
  hoverable(road, 'Straight highway at ground level',
    'The highway', 'A and B are mileposts on a straight, level road. The road is the horizontal base of both right triangles, so its distance d = AB is the one measured length that unlocks the figure.');

  /* teal dashed horizontal reference */
  var tealLine = draw.line(PXs, PYs, plotX(xmax - 0.02), PYs)
    .stroke({ color: COL.teal, width: Math.max(1.2, LW), dasharray: (FS * 0.55) + ',' + (FS * 0.42) });
  hoverable(tealLine, 'Horizontal reference line at the plane\'s altitude',
    'Angle of depression',
    'An angle of depression is always measured downward from the horizontal line through the observer — never from the vertical. That is why both angles are drawn between this teal line and a sight line.');

  /* sight lines */
  var dash = (FS * 0.5) + ',' + (FS * 0.38);
  var lineB = draw.line(PXs, PYs, BXs, FYs).stroke({ color: COL.sight, width: LW, dasharray: dash });
  var lineA = draw.line(PXs, PYs, AXs, FYs).stroke({ color: COL.sight, width: LW, dasharray: dash });
  hoverable(lineA, 'Sight line to A — depression ' + aAd + '°,  PA = ' + PA.toFixed(2) + ' mi',
    'Sight line to A', 'This is the hypotenuse of the small right triangle. tan(' + aAd + '°) = h / x relates the altitude to the ground distance x, and sin(' + aAd + '°) = h / PA gives the slant distance.');
  hoverable(lineB, 'Sight line to B — depression ' + aBd + '°,  PB = ' + PB.toFixed(2) + ' mi',
    'Sight line to B', 'This is the hypotenuse of the large right triangle. tan(' + aBd + '°) = h / (x + d): the same altitude h, but the longer ground leg, which is why the angle is smaller.');

  /* altitude + right angle */
  if (ph >= 1) {
    var alt = draw.line(PXs, PYs, FXs, FYs)
      .stroke({ color: COL.orange, width: Math.max(1.1, LW * 1.1), dasharray: (FS * 0.45) + ',' + (FS * 0.35) });
    hoverable(alt, 'Shared altitude h = ' + h.toFixed(2) + ' mi',
      'The shared altitude',
      'This single segment belongs to BOTH right triangles. The two depression angles are useless alone — it is the identical altitude h that couples the two tangent equations and lets one known road distance pin down every other length.');
    var sq = Math.max(5, FS * 0.62);
    draw.path('M' + FXs + ',' + (FYs - sq) + ' L' + (FXs + sq) + ',' + (FYs - sq) + ' L' + (FXs + sq) + ',' + FYs)
      .fill('none').stroke({ color: '#666', width: LW * 0.8 });
  }

  /* angle arcs */
  var dPA = Math.hypot(AXs - PXs, FYs - PYs);
  var r1 = Math.max(14, 0.26 * dPA), r2 = Math.max(24, 0.46 * dPA);
  draw.path(arcPath(PXs, PYs, r1, 0, aB)).fill('none').stroke({ color: '#555', width: LW * 0.85 });
  draw.path(arcPath(PXs, PYs, r2, 0, aA)).fill('none').stroke({ color: '#555', width: LW * 0.85 });

  var l1a = aB * 0.55, l1r = r1 + FS * 0.95;
  var l2a = aA * 0.40, l2r = r2 + FS * 0.85;
  var tB = txt(aBd + '°', PXs + l1r * Math.cos(l1a), PYs + l1r * Math.sin(l1a), { size: FS * 1.05 });
  var tA = txt(aAd + '°', PXs + l2r * Math.cos(l2a), PYs + l2r * Math.sin(l2a), { size: FS * 1.05 });
  hoverable(tB, 'Depression angle to the far milepost B = ' + aBd + '°',
    'The shallow angle', 'Measured from the teal horizontal down to the sight line to B. Push B farther away and this angle collapses toward 0°, while the angle to A never moves.');
  hoverable(tA, 'Depression angle to the near milepost A = ' + aAd + '°',
    'The steep angle', 'Measured from the teal horizontal down to the sight line to A. Since A is fixed, this angle depends only on the altitude: tan(angle) = h / x.');

  /* milepost dots + italic labels */
  var dotR = Math.max(2, FS * 0.22);
  var dA = draw.circle(dotR * 2).center(AXs, FYs).fill(COL.road);
  var dB = draw.circle(dotR * 2).center(BXs, FYs).fill(COL.road);
  hoverable(dA, 'Milepost A — ground distance x = ' + XA.toFixed(2) + ' mi from the foot of the altitude');
  hoverable(dB, 'Milepost B — ground distance x + d = ' + xB.toFixed(2) + ' mi from the foot of the altitude');
  txt('A', AXs, FYs + FS * 1.55, { italic: true, size: FS * 1.15 });
  txt('B', BXs, FYs + FS * 1.55, { italic: true, size: FS * 1.15 });

  /* unknown labels (phase >= 2) */
  if (ph >= 2) {
    txt('h', PXs - FS * 0.85, (PYs + FYs) / 2, { italic: true, size: FS * 1.15, fill: COL.orange });
    brace(FXs, AXs, FYs + FS * 2.9, 1, 'x', COL.orange);
    brace(FXs, BXs, FYs + FS * 4.8, 1, 'x + d', COL.blue);
    brace(AXs, BXs, FYs - FS * 1.25, -1, 'd = AB', '#8a5a00');
  }

  /* slant labels + equation callout (phase >= 3) */
  if (ph >= 3) {
    var uax = (AXs - PXs), uay = (FYs - PYs), la = Math.hypot(uax, uay);
    var pa = 0.55;
    txt('PA ≈ ' + PA.toFixed(2) + ' mi',
      PXs + uax * pa + (-uay / la) * FS * 1.2,
      PYs + uay * pa + (uax / la) * FS * 1.2,
      { size: FS * 0.92, fill: '#555' });
    var ubx = (BXs - PXs), uby = (FYs - PYs), lb = Math.hypot(ubx, uby);
    var pb = 0.45;
    txt('PB ≈ ' + PB.toFixed(2) + ' mi',
      PXs + ubx * pb + (uby / lb) * FS * 1.25,
      PYs + uby * pb + (-ubx / lb) * FS * 1.25,
      { size: FS * 0.92, fill: '#555' });

    var bfs = Math.max(8, Math.min(13, FS * 0.94));
    var lines = [
      'tan ' + aAd + '° = h / x',
      'tan ' + aBd + '° = h / (x + d)',
      'x = ' + XA.toFixed(2) + ' mi,  h = ' + h.toFixed(2) + ' mi',
      'PA = ' + PA.toFixed(2) + ',  PB = ' + PB.toFixed(2) + ' mi'
    ];
    var maxc = 0;
    for (var i = 0; i < lines.length; i++) maxc = Math.max(maxc, lines[i].length);
    var bw = Math.min(Wp * 0.52, maxc * bfs * 0.53 + 16);
    var bh = lines.length * bfs * 1.5 + 12;
    var bx = Math.max(4, Wp - bw - 6);
    var by = PYs + FS * 0.8;
    // keep the callout clear of the sight line to B
    var frac = (bx - PXs) / Math.max(1, BXs - PXs);
    if (frac > 0 && frac < 1) {
      var yLine = PYs + frac * (FYs - PYs);
      if (by + bh > yLine - 4) by = Math.max(3, yLine - bh - 5);
    }
    var box = draw.rect(bw, bh).move(bx, by).radius(4)
      .fill({ color: '#fffbe9', opacity: 0.96 }).stroke({ color: '#d9c98c', width: 1 });
    hoverable(box, 'Two equations in the two unknowns h and x',
      'Two equations, two unknowns',
      'tan(' + aAd + '°) = h/x and tan(' + aBd + '°) = h/(x+d) share the same h. Eliminating h gives x = d·tan(' + aBd + '°)/(tan(' + aAd + '°) − tan(' + aBd + '°)); back-substitution gives the altitude, and then the slant range PA follows from the sine ratio or the Pythagorean theorem.');
    for (var j = 0; j < lines.length; j++) {
      txt(lines[j], bx + 8, by + 8 + bfs * 0.75 + j * bfs * 1.5,
        { anchor: 'start', size: bfs, fill: j < 2 ? '#333' : '#8a5a00', halo: false });
    }
  }

  /* airplane (drawn last, on top of the converging lines) */
  var planeScale = 2.0 * scale / 100;
  var plane = drawPlane(PXs, PYs, planeScale);
  hoverable(plane, 'Observer P — altitude h = ' + h.toFixed(2) + ' mi',
    'The observer',
    'Everything is measured from the plane: the teal horizontal, both depression angles, and both slant sight lines. Raising the plane with A and B fixed steepens both sight lines at once, because each angle is set by a ratio of altitude to ground distance.');

